import type { Metadata } from "next";

export const SITE_URL = "https://maaptrix.com";

/** Homepage / site-wide default title and description (approved company messaging). */
export const SITE_TITLE = "Technology That Simplifies Real-World Operations | Maaptrix";
export const SITE_DESCRIPTION =
  "Maaptrix builds practical digital products that make everyday operations simpler, safer and more connected.";

/**
 * Site-wide share image generated by app/opengraph-image.tsx. Listed explicitly
 * because a page that sets its own `openGraph` replaces the inherited image.
 */
const SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Maaptrix: technology that simplifies real-world operations",
};

/**
 * Unique title, description, canonical URL, Open Graph and Twitter card data for a route.
 * `title` gets the " | Maaptrix" suffix unless `absolute` is set.
 */
export function pageMetadata(
  path: string,
  title: string,
  description: string,
  { absolute = false }: { absolute?: boolean } = {},
): Metadata {
  const fullTitle = absolute ? title : `${title} | Maaptrix`;
  return {
    title: absolute ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title: fullTitle,
      description,
      url: path,
      siteName: "Maaptrix",
      type: "website",
      locale: "en_IN",
      images: [SHARE_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [SHARE_IMAGE],
    },
  };
}
